import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import './Navbar.css';

function Navbar({ cartCount, onCartClick, user, onLogout }) {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [prevScrollY, setPrevScrollY] = useState(0);
  const [visible, setVisible] = useState(true);
  const navigate = useNavigate();

  // Scroll hide/show navbar
  useEffect(() => {
    const handleScroll = () => {
      const currentScrollY = window.scrollY;
      if (currentScrollY > prevScrollY && currentScrollY > 80) {
        setVisible(false);
      } else {
        setVisible(true);
      }
      setPrevScrollY(currentScrollY);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [prevScrollY]);

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 bg-[var(--cream)]/95 backdrop-blur-md border-b-4 border-[var(--saffron)] shadow-xl transition-transform duration-300" 
      style={{ 
        boxShadow: '0 4px 20px rgba(128,0,32,0.15)',
        transform: visible ? 'translateY(0)' : 'translateY(-100%)'
      }}>
      <div className="max-w-7xl mx-auto px-4 flex items-center justify-between h-16">
        <Link to="/" className="flex items-center gap-2 no-underline" onClick={() => setIsMenuOpen(false)}>
          <span className="text-3xl drop-shadow-lg hover:scale-110 transition-transform duration-200" style={{ filter: 'drop-shadow(0 2px 4px rgba(212,160,23,0.4))' }}>🍛</span>
          <div className="flex flex-col">
            <span className="font-serif font-bold text-xl leading-tight" style={{ 
              background: 'linear-gradient(135deg, var(--maroon), var(--saffron))',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              backgroundClip: 'text'
            }}>Riddhi Siddhi</span>
            <span className="text-xs" style={{ color: 'var(--chai)' }}>Modak Farsan</span>
          </div>
        </Link>

        <button className="md:hidden flex flex-col gap-1.5 bg-none border-none cursor-pointer p-1" onClick={() => setIsMenuOpen(!isMenuOpen)}>
          <span className={`block w-6 h-0.5 transition-all rounded ${isMenuOpen ? 'rotate-45 translate-y-1.5' : ''}`} style={{ background: 'var(--maroon)' }}></span>
          <span className={`block w-6 h-0.5 transition-all rounded ${isMenuOpen ? 'opacity-0' : ''}`} style={{ background: 'var(--maroon)' }}></span>
          <span className={`block w-6 h-0.5 transition-all rounded ${isMenuOpen ? '-rotate-45 -translate-y-1.5' : ''}`} style={{ background: 'var(--maroon)' }}></span>
        </button>

        <div className={`md:flex items-center gap-1 ${isMenuOpen ? 'flex flex-col absolute top-16 left-0 right-0 p-4 shadow-xl border-t-2 border-[var(--saffron)] animate-slide-up' : 'hidden'}`}
          style={{ background: 'var(--cream)' }}>
          <Link to="/" className="w-full md:w-auto px-3 py-2 text-sm font-medium rounded-lg transition-all duration-200 hover:scale-105 hover:bg-[var(--rose)]" 
            style={{ color: 'var(--maroon)' }}
            onClick={() => setIsMenuOpen(false)}>🏠 Home</Link>
          <Link to="/category/Dry Snacks" className="w-full md:w-auto px-3 py-2 text-sm font-medium rounded-lg transition-all duration-200 hover:scale-105 hover:bg-[var(--rose)]"
            style={{ color: '#666' }}
            onClick={() => setIsMenuOpen(false)}>🥨 Dry Snacks</Link>
          <Link to="/category/Namkeen" className="w-full md:w-auto px-3 py-2 text-sm font-medium rounded-lg transition-all duration-200 hover:scale-105 hover:bg-[var(--rose)]"
            style={{ color: '#666' }}
            onClick={() => setIsMenuOpen(false)}>🥟 Namkeen</Link>
          <Link to="/category/Sweets" className="w-full md:w-auto px-3 py-2 text-sm font-medium rounded-lg transition-all duration-200 hover:scale-105 hover:bg-[var(--rose)]"
            style={{ color: '#666' }}
            onClick={() => setIsMenuOpen(false)}>🍬 Sweets</Link>
          <Link to="/category/Wet Sweets" className="w-full md:w-auto px-3 py-2 text-sm font-medium rounded-lg transition-all duration-200 hover:scale-105 hover:bg-[var(--rose)]"
            style={{ color: '#666' }}
            onClick={() => setIsMenuOpen(false)}>🍮 Fresh Sweets</Link>
          {user ? (
            <>
              <Link to="/dashboard" className="w-full md:w-auto px-3 py-2 text-sm font-medium rounded-lg transition-all duration-200 hover:scale-105 hover:bg-[var(--rose)]"
                style={{ color: '#666' }}
                onClick={() => setIsMenuOpen(false)}>📋 Orders</Link>
              <button className="w-full md:w-auto px-3 py-2 text-sm font-medium rounded-lg transition-all duration-200 hover:scale-105 hover:bg-[var(--rose)] bg-none border-none cursor-pointer text-left md:text-center"
                style={{ color: '#666' }}
                onClick={() => { onLogout(); setIsMenuOpen(false); navigate('/'); }}>🚪 Logout</button>
            </>
          ) : (
            <Link to="/checkout" className="w-full md:w-auto px-3 py-2 text-sm font-medium rounded-lg transition-all duration-200 hover:scale-105 hover:bg-[var(--rose)]"
              style={{ color: '#666' }}
              onClick={() => setIsMenuOpen(false)}>👤 Login</Link>
          )}
        </div>

        <button className="relative bg-none border-none cursor-pointer p-2 rounded-full transition-all duration-200 hover:scale-110 hover:bg-[var(--rose)] active:scale-95" onClick={onCartClick}>
          <span className="text-xl">🛒</span>
          {cartCount > 0 && (
            <span className="absolute -top-0.5 -right-0.5 text-white text-xs font-bold w-5 h-5 rounded-full flex items-center justify-center shadow-lg animate-bounce-in"
              style={{ background: 'linear-gradient(135deg, var(--maroon), var(--saffron))' }}>
              {cartCount}
            </span>
          )}
        </button>
      </div>
    </nav>
  );
}

export default Navbar;
